@startuml

class Client {
  + NIN : string
  + TIN : string
  + Name : string
  + Address : string
}

class BicycleModel {
  + Name : string
  + Type : BicycleType
  + NumberOfGears : int
}

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Bicycle {
  + IdentifyingNumber : string
}

class Store {
  + Name : string
  + Address : string
}

class Reservation {
  + PickupDate : date
}

class Rental {
  + ReturnDate : date
}

BicycleModel "1" -- "*" Bicycle : is model of
Bicycle "1" -- "1" BicycleModel : is a type of
Client "1" -- "*" Reservation : makes
BicycleModel "1" -- "*" Reservation : requested in
Store "1" -- "*" Reservation : pickup location
Reservation "1" -- "0..1" Rental : results in
Bicycle "1" -- "0..1" Rental : is rented in
Store "1" -- "*" Rental : return location

@enduml

